#define FMRB_SDK_VERSION_H

#define FMRB_SDK_VERSION_MAJOR 0
#define FMRB_SDK_VERSION_MINOR 1
#define FMRB_SDK_VERSION_PATCH 0
#define FMRB_SDK_VERSION "0.1.0"
